-- ============================================================
-- Vegan Meal Planner - seed data (T-SQL / SQL Server syntax)
-- Generated from vegan_meal_planner_dataset_validated.xlsx
-- Source data: Mendeley "Vegan_datasets" (ChatGPT-generated, 3-dietitian validated)
-- Rule-based selection only, no free-form AI generation.
-- ============================================================

-- ==================== SCHEMA ====================

CREATE TABLE allergens (
  id BIGINT NOT NULL PRIMARY KEY,
  code NVARCHAR(20) NOT NULL,
  name NVARCHAR(100) NOT NULL
);
GO

CREATE TABLE ingredients (
  id BIGINT NOT NULL PRIMARY KEY,
  name NVARCHAR(255) NOT NULL,
  meal_role NVARCHAR(30) NOT NULL,
  is_vegan BIT NOT NULL,
  kcal_per_100g DECIMAL(7,2) NULL,
  protein_g_per_100g DECIMAL(7,2) NULL,
  carb_g_per_100g DECIMAL(7,2) NULL,
  fat_g_per_100g DECIMAL(7,2) NULL,
  nutrition_source NVARCHAR(255) NULL
);
GO

CREATE TABLE ingredient_suitability (
  ingredient_id BIGINT NOT NULL,
  ingredient_name NVARCHAR(255) NOT NULL,
  weight_group NVARCHAR(20) NOT NULL,
  allergy_group NVARCHAR(20) NOT NULL,
  expert_agreement DECIMAL(5,2) NOT NULL,
  is_suitable BIT NOT NULL,
  condition_note NVARCHAR(1000) NULL,
  source_file NVARCHAR(255) NULL,
  CONSTRAINT PK_ingredient_suitability PRIMARY KEY (ingredient_id, weight_group, allergy_group),
  CONSTRAINT FK_suitability_ingredient FOREIGN KEY (ingredient_id) REFERENCES ingredients(id)
);
GO

CREATE TABLE ingredient_allergens (
  ingredient_id BIGINT NOT NULL,
  ingredient_name NVARCHAR(255) NOT NULL,
  allergen_id BIGINT NOT NULL,
  allergen_code NVARCHAR(20) NOT NULL,
  certainty NVARCHAR(20) NOT NULL,
  note NVARCHAR(500) NULL,
  tag_source NVARCHAR(20) NOT NULL,
  CONSTRAINT PK_ingredient_allergens PRIMARY KEY (ingredient_id, allergen_id),
  CONSTRAINT FK_ingalg_ingredient FOREIGN KEY (ingredient_id) REFERENCES ingredients(id),
  CONSTRAINT FK_ingalg_allergen FOREIGN KEY (allergen_id) REFERENCES allergens(id)
);
GO

CREATE TABLE users_synthetic (
  id BIGINT NOT NULL PRIMARY KEY,
  weight_group NVARCHAR(20) NOT NULL,
  allergy_group NVARCHAR(20) NOT NULL,
  height_cm DECIMAL(5,2) NOT NULL
);
GO

CREATE TABLE user_allergen_groups (
  user_id BIGINT NOT NULL,
  allergen_id BIGINT NOT NULL,
  allergen_code NVARCHAR(20) NOT NULL,
  CONSTRAINT PK_user_allergen_groups PRIMARY KEY (user_id, allergen_id),
  CONSTRAINT FK_uag_user FOREIGN KEY (user_id) REFERENCES users_synthetic(id),
  CONSTRAINT FK_uag_allergen FOREIGN KEY (allergen_id) REFERENCES allergens(id)
);
GO

CREATE TABLE meals (
  id BIGINT NOT NULL PRIMARY KEY,
  owner_user_id BIGINT NULL,
  combo_name NVARCHAR(500) NOT NULL,
  description NVARCHAR(1000) NULL,
  servings INT NOT NULL,
  total_calories DECIMAL(8,2) NULL,
  diet_type NVARCHAR(30) NOT NULL,
  meal_time_hint NVARCHAR(20) NOT NULL,
  created_at DATETIME2 NOT NULL,
  CONSTRAINT FK_meals_owner FOREIGN KEY (owner_user_id) REFERENCES users_synthetic(id)
);
GO

CREATE TABLE meal_ingredients (
  meal_id BIGINT NOT NULL,
  ingredient_id BIGINT NOT NULL,
  ingredient_name NVARCHAR(255) NOT NULL,
  calculated_quantity DECIMAL(8,2) NULL,
  unit NVARCHAR(10) NOT NULL,
  grams DECIMAL(8,2) NULL,
  CONSTRAINT PK_meal_ingredients PRIMARY KEY (meal_id, ingredient_id),
  CONSTRAINT FK_mi_meal FOREIGN KEY (meal_id) REFERENCES meals(id),
  CONSTRAINT FK_mi_ingredient FOREIGN KEY (ingredient_id) REFERENCES ingredients(id)
);
GO

CREATE TABLE meal_plans (
  id BIGINT NOT NULL PRIMARY KEY,
  user_id BIGINT NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  height_cm DECIMAL(5,2) NOT NULL,
  weight_kg DECIMAL(6,2) NOT NULL,
  bmi_value DECIMAL(6,2) NOT NULL,
  diet_type NVARCHAR(30) NOT NULL,
  allergies_snapshot NVARCHAR(MAX) NOT NULL,
  available_ingredients_snapshot NVARCHAR(MAX) NOT NULL,
  generation_source NVARCHAR(20) NOT NULL,
  model_name NVARCHAR(100) NULL,
  status NVARCHAR(20) NOT NULL,
  error_message NVARCHAR(2000) NULL,
  created_at DATETIME2 NOT NULL,
  updated_at DATETIME2 NULL,
  saved_at DATETIME2 NULL,
  CONSTRAINT FK_meal_plans_user FOREIGN KEY (user_id) REFERENCES users_synthetic(id)
);
GO

CREATE TABLE meal_plan_schedule (
  id BIGINT NOT NULL PRIMARY KEY,
  meal_plan_id BIGINT NOT NULL,
  meal_id BIGINT NOT NULL,
  day_of_week INT NOT NULL,
  meal_time NVARCHAR(20) NOT NULL,
  portion_multiplier DECIMAL(4,2) NOT NULL,
  CONSTRAINT FK_schedule_plan FOREIGN KEY (meal_plan_id) REFERENCES meal_plans(id),
  CONSTRAINT FK_schedule_meal FOREIGN KEY (meal_id) REFERENCES meals(id)
);
GO

