-- ==================== VIEW ====================

CREATE VIEW meal_plan_view AS
SELECT
  s.meal_plan_id,
  s.day_of_week AS day_number,
  DATEADD(DAY, s.day_of_week - 1, p.start_date) AS meal_date,
  s.meal_time AS meal_type,
  STRING_AGG(mi.ingredient_name, ', ') AS foods
FROM meal_plan_schedule s
JOIN meal_plans p ON p.id = s.meal_plan_id
JOIN meal_ingredients mi ON mi.meal_id = s.meal_id
GROUP BY s.meal_plan_id, s.day_of_week, p.start_date, s.meal_time;
GO
